"""
LLM planning layer for AgentGuard.

The LLM understands the user's request and converts it
into a structured action.

The LLM does NOT decide whether the action is safe.
The TrustEngine remains the security authority.
"""

import os
from dotenv import load_dotenv
from pydantic import BaseModel, Field
from langchain_google_genai import ChatGoogleGenerativeAI

load_dotenv()


class AgentAction(BaseModel):
    """Structured action generated by the AI agent."""

    action: str = Field(
        description="Action to perform, such as payment.send, email.send, "
                    "customer_data.export, or database.delete."
    )

    amount: float | None = Field(
        default=None,
        description="Payment amount when the action is payment.send."
    )

    recipient: str | None = Field(
        default=None,
        description="Payment recipient."
    )

    external: bool = Field(
        default=False,
        description="Whether the action involves an external destination."
    )

    destination: str | None = Field(
        default=None,
        description="External destination."
    )

    to: str | None = Field(
        default=None,
        description="Email recipient."
    )

    subject: str | None = Field(
        default=None,
        description="Email subject."
    )

    record_id: str | None = Field(
        default=None,
        description="Database record ID."
    )


def create_gemini_agent():
    api_key = os.getenv("GOOGLE_API_KEY")

    if not api_key:
        raise RuntimeError(
            "GOOGLE_API_KEY is not configured. "
            "Create a .env file and add GOOGLE_API_KEY."
        )

    llm = ChatGoogleGenerativeAI(
        model="gemini-2.5-flash",
        temperature=0
    )

    return llm.with_structured_output(AgentAction)


def understand_request(user_request: str) -> AgentAction:

    agent = create_gemini_agent()

    prompt = f"""
You are the planning component of AgentGuard.

Your job is to understand the user's request and convert it
into a structured action.

You MUST NOT execute the action.

Supported actions:

- payment.send
- email.send
- customer_data.export
- database.delete

Rules:

1. Never invent missing information.
2. Use null when a value is not available.
3. Extract payment amount when present.
4. Extract payment recipient when present.
5. Extract database record ID when present.
6. Extract email recipient and subject when present.
7. Set external=true ONLY when the user explicitly says the destination is external,
   outside the organization, a third party, or an external system.
8. If the user does not explicitly indicate an external destination, set external=false.
9. Do not infer external=true merely because a recipient is a vendor.
10. Do not decide whether the action is safe.
11. Do not bypass AgentGuard policies.
User request:

{user_request}
"""

    return agent.invoke(prompt)


if __name__ == "__main__":

    user_request = input("Enter your request: ")

    result = understand_request(user_request)

    print("\n=== AI Agent Result ===")
    print(result.model_dump_json(indent=2))